<template><AppShell><StatePanel v-if="loading||error" :loading="loading" :error="error" @retry="load"/><template v-else-if="person"><view class="detail-crumb"><button class="text-button" @tap="go('people')">← 人物索引</button><text>人物档案 / {{person.id}}</text></view><PersonPanorama v-if="person.id==='P009'"/><view v-else class="person-cover"><PersonPortrait :person-id="person.id" :name="person.name" variant="cover"/><view class="person-cover-copy"><text class="eyebrow">人物档案 / HERO ARCHIVE</text><text class="person-cover-name">{{person.name}}</text><text class="cover-sub">{{person.aliases.length?'别名 · '+person.aliases.join(' / '):'山河有迹 · 史料为据'}}</text></view><text class="cover-stamp">循迹<br/>读人</text></view><view class="reading-chapters"><button @tap="section('person-intro')">人物概览</button><button @tap="section('person-chronicle')">生平片段</button><button @tap="section('person-evidence')">史料依据</button><button @tap="section('person-next')">继续循迹</button></view><view class="detail-layout"><view class="detail-main"><view id="person-intro" class="section-heading compact"><view><text class="eyebrow">01 / 走近人物</text><text class="section-title">{{person.name}}的时代片段</text></view></view><text class="reading-body" :class="{'reading-large':large}">{{person.bio}}</text><view class="person-shortcuts"><button @tap="go('timeline',{person_id:person.id})"><image class="shortcut-icon shortcut-timeline" src="/static/icons/timeline.png" aria-hidden="true"/><text>长卷</text><text class="small">生平片段</text></button><button @tap="go('graph',{id:person.id})"><image class="shortcut-icon shortcut-graph" src="/static/icons/graph.png" aria-hidden="true"/><text>图谱</text><text class="small">人物关系</text></button><button @tap="go('sources',{id:person.id})"><image class="shortcut-icon shortcut-source" src="/static/icons/source.png" aria-hidden="true"/><text>史料</text><text class="small">来源依据</text></button><button v-if="challengeGroup(person.id)" @tap="go('learning',{group:challengeGroup(person.id)})"><image class="shortcut-icon shortcut-learning" src="/static/icons/learning.png" aria-hidden="true"/><text>挑战</text><text class="small">读后巩固</text></button></view><view class="identity-grid"><view><text>出生省份</text><text>{{person.province}}</text></view><view><text>出生记载</text><button v-if="person.birth" class="inline-source" @tap="sourceId=person.birth.source_id">{{person.birth.text}} ↗</button><text v-else>资料待核</text></view><view><text>逝世纪录</text><button v-if="person.death" class="inline-source" @tap="sourceId=person.death.source_id">{{person.death.text}} ↗</button><text v-else>资料待核</text></view></view><view id="person-chronicle" class="section-heading compact"><view><text class="eyebrow">02 / 沿着年代</text><text class="section-title">有据可循的节点</text></view><button class="text-button" @tap="go('timeline',{person_id:person.id})">完整片段 ↗</button></view><view v-for="e in person.events.slice(0,4)" :key="e.id" class="chronicle-row" @tap="go('event',{id:e.id})"><view class="chronicle-date"><text>{{e.date_text}}</text><text class="timeline-dot"/></view><view><text class="row-title">{{e.title}}</text><text class="row-summary">{{e.summary}}</text><text class="small">阅读片段 ↗</text></view></view><StatePanel v-if="!person.events.length" title="有日期的片段仍在整理" message="已收录事实可以在资料来源中阅读。"/><view id="person-evidence" class="section-heading compact"><view><text class="eyebrow">03 / 史料摘读</text><text class="section-title">看记载，也看依据</text></view></view><view v-for="f in person.facts.slice(0,3)" :key="f.id" class="fact-card"><text class="tag">{{f.review_status==='attributed'?'来源归因记载':'已核来源记载'}}</text><text class="reading-body" :class="{'reading-large':large}">{{f.text}}</text><button class="text-button" @tap="sourceId=f.source_id">查看引用定位与支持范围 ↗</button></view><view class="remaining-panel"><button class="remaining-toggle" @tap="expanded=!expanded"><text>哪些内容仍待求证？</text><text>{{expanded?'−':'＋'}}</text></button><text v-if="expanded" class="muted">{{person.remaining}}</text></view></view><view class="detail-aside"><text class="eyebrow">继续循迹</text><view class="reading-links"><button @tap="go('timeline',{person_id:person.id})"><image src="/static/icons/timeline.png"/><view><text>人生长卷</text><text>按年代展开片段</text></view><text>↗</text></button><button @tap="go('graph',{id:person.id})"><image src="/static/icons/graph.png"/><view><text>人物关系</text><text>每一条关联都有依据</text></view><text>↗</text></button><button @tap="go('sources',{id:person.id})"><image src="/static/icons/book.png"/><view><text>事实与来源</text><text>{{person.source_count}} 份公开阅读来源</text></view><text>↗</text></button></view><button class="primary" @tap="save">{{saved?'移除本机书签':'添加本机书签'}}</button><text class="small local-note">仅保存在本机，不同步账户</text><view class="aside-note"><text class="serif">史料为据</text><text>人物简介为现有已核材料的来源限定整理，完整生平持续补充。</text></view></view></view><view id="person-next" class="next-actions"><button v-if="challengeGroup(person.id)" class="outline" @tap="go('learning',{group:challengeGroup(person.id)})">学习挑战 · 读后巩固</button><button class="text-button" @tap="go('assistant',{person_id:person.id,name:person.name})">问小迹 · 带上人物背景</button><button class="text-button" @tap="go('radar',{person_id:person.id})">探索关联场馆</button><button class="text-button" @tap="go('discussion',{topicId:person.id})">分享阅读感受 · 评论先审核</button></view></template><SourceSheet :source-id="sourceId" @close="sourceId=''"/></AppShell></template>
<script setup>
import PersonPanorama from '../../components/PersonPanorama.vue';import PersonPortrait from '../../components/PersonPortrait.vue';import {challengeGroup} from '../../lib/learning.js';import {ref,onMounted,onBeforeUnmount} from 'vue';import {onPageScroll,onLoad,onShow,onShareAppMessage} from '@dcloudio/uni-app';import AppShell from '../../components/AppShell.vue';import StatePanel from '../../components/StatePanel.vue';import SourceSheet from '../../components/SourceSheet.vue';import {api} from '../../lib/api.js';import {go} from '../../lib/navigation.js';import {remember,toggleBookmark,isSaved,prefs} from '../../lib/reading.js'
const person=ref(null),loading=ref(true),error=ref(''),sourceId=ref(''),saved=ref(false),expanded=ref(false),large=ref(false);let id='P009'
let requestSequence=0
async function load(){const sequence=++requestSequence,requestedId=id;loading.value=true;error.value='';try{const data=await api('people/'+requestedId);if(sequence!==requestSequence)return;person.value=data;remember('person',requestedId,data.name);saved.value=isSaved('person',requestedId)}catch(e){if(sequence===requestSequence)error.value=e.message}finally{if(sequence===requestSequence)loading.value=false}}
function section(id){uni.pageScrollTo({selector:'#'+id,duration:220})}
function save(){saved.value=toggleBookmark('person',id,person.value.name);uni.showToast({title:saved.value?'本机书签已添加':'书签已移除',icon:'none'})}
onLoad(options=>{id=options.id||'P009';load()});onShow(()=>{large.value=prefs().size==='large';saved.value=isSaved('person',id)});onShareAppMessage(()=>({title:'走近'+(person.value?.name||'人物')+' · 山河有迹',path:'/pages/person/index?id='+id}))
let readingScroll=0;onPageScroll(e=>{readingScroll=e.scrollTop});onShow(()=>{if(readingScroll>0){const target=readingScroll;setTimeout(()=>uni.pageScrollTo({scrollTop:target,duration:0}),250)}});
// #ifdef H5
function syncPersonRoute(){const [route,query='']=location.hash.slice(1).split('?');if(route!=='/pages/person/index')return;const nextId=new URLSearchParams(query).get('id')||'P009';if(nextId!==id){id=nextId;person.value=null;expanded.value=false;sourceId.value='';readingScroll=0;load()}}
onShow(syncPersonRoute)
onMounted(()=>window.addEventListener('hashchange',syncPersonRoute));onBeforeUnmount(()=>window.removeEventListener('hashchange',syncPersonRoute))
// #endif
</script>
